#!/usr/bin/env python3
"""Offline SIP identity-boundary processor (protocol revision 1).

The program reads one batch JSON object from stdin and writes one results JSON
object to stdout.  It deliberately implements only the grammar and policy in
PROTOCOL.md; no network or third-party packages are used.
"""

import json
import re
import sys


MAX_REQUEST_CHARS = 32768
ANONYMOUS_URI = "sip:anonymous@anonymous.invalid"

TOKEN_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    "-.!%*_+`'~"
)
USER_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    "-_.!~*'()+"
)
CALL_ID_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.@+-"
)
HEX_CHARS = frozenset("0123456789abcdefABCDEF")
ASCII_ALNUM = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
)

REQUIRED_SINGLETONS = frozenset(
    ("from", "to", "call-id", "cseq", "content-length")
)
OPTIONAL_SINGLETONS = frozenset(
    ("pp-preferred-identity", "remote-party-id", "privacy", "content-type")
)
COMPACT_NAMES = {
    "f": "from",
    "t": "to",
    "i": "call-id",
    "l": "content-length",
    "c": "content-type",
}
CANONICAL_SINGLETON_NAMES = REQUIRED_SINGLETONS | OPTIONAL_SINGLETONS
PAI_NAME = "p-asserted-identity"

CSEQ_RE = re.compile(r"([0-9]+)[ \t]+(INVITE|MESSAGE)\Z")
DIGITS_RE = re.compile(r"[0-9]+\Z")


class SIPFailure(Exception):
    """The supplied request violates the syntax rules."""


class IdentityFailure(Exception):
    """A syntactically valid claim fails identity policy at a boundary."""


def _is_hex_char(c):
    return c in HEX_CHARS


def _validate_host(host):
    """Validate and normalize a DNS-name host from a sip URI."""
    if not host:
        raise SIPFailure()
    if host.endswith("."):
        base = host[:-1]
    else:
        base = host
    if not base or len(base) > 253:
        raise SIPFailure()
    labels = base.split(".")
    for label in labels:
        if not (1 <= len(label) <= 63):
            raise SIPFailure()
        for c in label:
            if c not in ASCII_ALNUM and c != "-":
                raise SIPFailure()
        if label[0] not in ASCII_ALNUM or label[-1] not in ASCII_ALNUM:
            raise SIPFailure()
    return base.lower()


def _parse_sip_uri(uri):
    """Parse a sip URI and return (canonical URI, 'sip')."""
    if len(uri) < 4 or uri[3] != ":" or uri[:3].lower() != "sip":
        raise SIPFailure()
    rest = uri[4:]
    at = rest.find("@")
    if at < 0:
        raise SIPFailure()
    raw_user = rest[:at]
    raw_host = rest[at + 1:]
    if not raw_user:
        raise SIPFailure()

    decoded_user = []
    i = 0
    n = len(raw_user)
    while i < n:
        c = raw_user[i]
        if c == "%":
            if i + 2 >= n:
                raise SIPFailure()
            h1, h2 = raw_user[i + 1], raw_user[i + 2]
            if not _is_hex_char(h1) or not _is_hex_char(h2):
                raise SIPFailure()
            decoded = chr(int(h1 + h2, 16))
            if decoded not in USER_CHARS:
                raise SIPFailure()
            decoded_user.append(decoded)
            i += 3
        elif c in USER_CHARS:
            decoded_user.append(c)
            i += 1
        else:
            raise SIPFailure()
    if not decoded_user:
        raise SIPFailure()

    host = _validate_host(raw_host)
    return "sip:" + "".join(decoded_user) + "@" + host, "sip"


def _parse_tel_uri(uri):
    """Parse a tel URI and return (canonical URI, 'tel')."""
    if len(uri) < 5 or uri[:4].lower() != "tel:" or uri[4] != "+":
        raise SIPFailure()
    digits = uri[5:]
    if not (1 <= len(digits) <= 15):
        raise SIPFailure()
    if not DIGITS_RE.fullmatch(digits):
        raise SIPFailure()
    if digits[0] == "0":
        raise SIPFailure()
    return "tel:+" + digits, "tel"


def parse_uri(uri):
    """Parse a URI under the permitted sip/tel grammar.

    Returns (normalized_uri, scheme), where scheme is 'sip' or 'tel'.
    """
    lowered = uri[:4].lower()
    if lowered == "sip:":
        return _parse_sip_uri(uri)
    if lowered == "tel:":
        return _parse_tel_uri(uri)
    raise SIPFailure()


def _skip_sp_htab(s, pos):
    n = len(s)
    while pos < n and (s[pos] == " " or s[pos] == "\t"):
        pos += 1
    return pos


def _parse_quoted_display(s, pos):
    """Return the position just after a valid quoted display string."""
    n = len(s)
    pos += 1  # opening quote
    while pos < n:
        c = s[pos]
        if c == '"':
            return pos + 1
        if c == "\\":
            pos += 1
            if pos >= n:
                raise SIPFailure()
            escaped = s[pos]
            if escaped != "\t" and not (" " <= escaped <= "~"):
                raise SIPFailure()
            pos += 1
        else:
            pos += 1
    raise SIPFailure()


def _parse_uri_from_bare_or_angle(s):
    """Parse exactly one address with no From/To tag.

    Returns (normalized_uri, scheme).
    """
    s = s.strip(" \t")
    if not s:
        raise SIPFailure()

    # A bare URI is the first possible form; trying it first also resolves the
    # only ambiguity between a bare URI and a display token followed by '<'.
    try:
        return parse_uri(s)
    except SIPFailure:
        pass

    if s[0] == "<":
        left_angle = 0
    elif s[0] == '"':
        pos = _parse_quoted_display(s, 0)
        pos = _skip_sp_htab(s, pos)
        if pos >= len(s) or s[pos] != "<":
            raise SIPFailure()
        left_angle = pos
    else:
        if s[0] not in TOKEN_CHARS:
            raise SIPFailure()
        pos = 0
        n = len(s)
        while True:
            if pos >= n or s[pos] not in TOKEN_CHARS:
                raise SIPFailure()
            while pos < n and s[pos] in TOKEN_CHARS:
                pos += 1
            if pos < n and s[pos] == "<":
                left_angle = pos
                break
            if pos < n and (s[pos] == " " or s[pos] == "\t"):
                q = _skip_sp_htab(s, pos)
                if q < n and s[q] == "<":
                    left_angle = q
                    break
                if q < n and s[q] in TOKEN_CHARS:
                    pos = q
                    continue
            raise SIPFailure()

    right_angle = s.find(">", left_angle + 1)
    if right_angle < 0:
        raise SIPFailure()
    interior = s[left_angle + 1:right_angle]
    if "<" in interior:
        raise SIPFailure()
    interior = interior.strip(" \t")
    if not interior:
        raise SIPFailure()
    uri, scheme = parse_uri(interior)
    if s[right_angle + 1:].strip(" \t"):
        raise SIPFailure()
    return uri, scheme


def _find_top_level_semicolon(s):
    """Find a semicolon outside quoted display data and angle brackets."""
    in_quote = False
    escaped = False
    in_angle = False
    for i, c in enumerate(s):
        if in_quote:
            if escaped:
                escaped = False
            elif c == "\\":
                escaped = True
            elif c == '"':
                in_quote = False
        else:
            if c == '"':
                in_quote = True
            elif c == "<":
                in_angle = True
            elif c == ">":
                in_angle = False
            elif c == ";" and not in_angle:
                return i
    return -1


def parse_from_or_to(value):
    """Parse From/To value, returning ((uri, scheme), tag_or_None)."""
    semi = _find_top_level_semicolon(value)
    if semi < 0:
        return _parse_uri_from_bare_or_angle(value), None

    address_part = value[:semi].strip(" \t")
    if not address_part:
        raise SIPFailure()
    parsed = _parse_uri_from_bare_or_angle(address_part)

    tag_part = value[semi:]
    m = re.fullmatch(
        r";[ \t]*[Tt][Aa][Gg][ \t]*=[ \t]*([^ \t]+)[ \t]*",
        tag_part,
    )
    if m is None:
        raise SIPFailure()
    tag = m.group(1)
    if not (1 <= len(tag) <= 128):
        raise SIPFailure()
    for c in tag:
        if c not in TOKEN_CHARS:
            raise SIPFailure()
    return parsed, tag


def parse_single_address(value):
    """Parse an address value that may not carry header parameters."""
    return _parse_uri_from_bare_or_angle(value)


def _split_pai_list(value):
    """Split one PAI field into addresses at commas outside quotes/angles."""
    pieces = []
    start = 0
    in_quote = False
    escaped = False
    in_angle = False
    for i, c in enumerate(value):
        if in_quote:
            if escaped:
                escaped = False
            elif c == "\\":
                escaped = True
            elif c == '"':
                in_quote = False
        else:
            if c == '"':
                in_quote = True
            elif c == "<":
                in_angle = True
            elif c == ">":
                in_angle = False
            elif c == "," and not in_angle:
                pieces.append(value[start:i])
                start = i + 1
    pieces.append(value[start:])
    result = []
    for piece in pieces:
        piece = piece.strip(" \t")
        if not piece:
            raise SIPFailure()
        result.append(piece)
    return result


def _char_is_ascii_printable_or_tab(c):
    return c == "\t" or (" " <= c <= "~")


def _check_header_section_chars(header_section):
    # CR and LF have already served as line separators; any remaining CR/LF,
    # other control, DEL, or non-ASCII character is invalid in a header line.
    for c in header_section:
        if c == "\r" or c == "\n":
            raise SIPFailure()
        if c != "\t" and not (" " <= c <= "~"):
            raise SIPFailure()


def _check_body_chars(body):
    for c in body:
        if c == "\t" or c == "\r" or c == "\n":
            continue
        if not (" " <= c <= "~"):
            raise SIPFailure()


def _parse_header_fields(field_lines):
    """Unfold fields, returning [(lower-case expanded name, trimmed value)]."""
    if len(field_lines) > 512:
        raise SIPFailure()

    logical = []  # [lower-case original name, accumulated raw value]
    for line in field_lines:
        if line and (line[0] == " " or line[0] == "\t"):
            if not logical:
                raise SIPFailure()
            continuation = line.lstrip(" \t")
            logical[-1][1] += " " + continuation
            continue

        colon = line.find(":")
        if colon < 0:
            raise SIPFailure()
        name_part = line[:colon].rstrip(" \t")
        if not name_part:
            raise SIPFailure()
        for c in name_part:
            if c not in TOKEN_CHARS:
                raise SIPFailure()
        value = line[colon + 1:]
        logical.append([name_part.lower(), value])
        if len(logical) > 128:
            raise SIPFailure()

    expanded = []
    for name, value in logical:
        canonical_name = COMPACT_NAMES.get(name, name)
        expanded.append((canonical_name, value.strip(" \t")))
    return expanded


def _parse_cseq(value, method):
    m = CSEQ_RE.fullmatch(value)
    if m is None or m.group(2) != method:
        raise SIPFailure()
    canonical_number = m.group(1).lstrip("0")
    if not canonical_number:
        raise SIPFailure()
    if len(canonical_number) > 10:
        raise SIPFailure()
    if len(canonical_number) == 10 and canonical_number > "2147483647":
        raise SIPFailure()
    return canonical_number


def _parse_request(text):
    """Parse and fully syntax-validate one request.

    Returns a dictionary of all fields needed by policy and canonical output.
    Raises SIPFailure for any syntax problem.
    """
    if not isinstance(text, str) or len(text) > MAX_REQUEST_CHARS:
        raise SIPFailure()

    split_at = text.find("\r\n\r\n")
    if split_at < 0:
        raise SIPFailure()
    header_section = text[:split_at]
    body = text[split_at + 4:]

    _check_header_section_chars(header_section)
    _check_body_chars(body)

    lines = header_section.split("\r\n")
    request_line = lines[0]
    field_lines = lines[1:]

    request_parts = request_line.split(" ")
    if len(request_parts) != 3:
        raise SIPFailure()
    method, request_uri_text, version = request_parts
    if method not in ("INVITE", "MESSAGE"):
        raise SIPFailure()
    if version != "SIP/2.0":
        raise SIPFailure()
    request_uri, request_scheme = parse_uri(request_uri_text)
    if request_scheme != "sip":
        raise SIPFailure()

    fields = _parse_header_fields(field_lines)

    required_values = {name: [] for name in REQUIRED_SINGLETONS}
    optional_values = {name: [] for name in OPTIONAL_SINGLETONS}
    pai_field_values = []

    for name, value in fields:
        if name in required_values:
            required_values[name].append(value)
        elif name in optional_values:
            optional_values[name].append(value)
        elif name == PAI_NAME:
            pai_field_values.append(value)
        # Other fields have no semantics, as specified.

    for name in REQUIRED_SINGLETONS:
        if len(required_values[name]) != 1:
            raise SIPFailure()
    for name in OPTIONAL_SINGLETONS:
        if len(optional_values[name]) > 1:
            raise SIPFailure()

    from_value = required_values["from"][0]
    to_value = required_values["to"][0]
    call_id = required_values["call-id"][0]
    cseq_value = required_values["cseq"][0]
    content_length_value = required_values["content-length"][0]

    if not (1 <= len(call_id) <= 128):
        raise SIPFailure()
    for c in call_id:
        if c not in CALL_ID_CHARS:
            raise SIPFailure()

    cseq_number = _parse_cseq(cseq_value, method)

    if not DIGITS_RE.fullmatch(content_length_value):
        raise SIPFailure()
    canonical_content_length = content_length_value.lstrip("0") or "0"
    if canonical_content_length != str(len(body)):
        raise SIPFailure()

    content_type = None
    if optional_values["content-type"]:
        content_type = optional_values["content-type"][0]
        if not content_type:
            raise SIPFailure()
        for c in content_type:
            if not _char_is_ascii_printable_or_tab(c):
                raise SIPFailure()

    privacy = None
    if optional_values["privacy"]:
        privacy = optional_values["privacy"][0].lower()
        if privacy not in ("id", "none"):
            raise SIPFailure()

    (from_uri, from_scheme), from_tag = parse_from_or_to(from_value)
    (to_uri, to_scheme), to_tag = parse_from_or_to(to_value)

    ppi_parsed = None
    if optional_values["pp-preferred-identity"]:
        ppi_parsed = parse_single_address(
            optional_values["pp-preferred-identity"][0]
        )
        if ppi_parsed[0] == ANONYMOUS_URI:
            raise SIPFailure()

    rpid_parsed = None
    if optional_values["remote-party-id"]:
        rpid_parsed = parse_single_address(
            optional_values["remote-party-id"][0]
        )
        if rpid_parsed[0] == ANONYMOUS_URI:
            raise SIPFailure()

    pai_parsed = []
    for field_value in pai_field_values:
        for address_text in _split_pai_list(field_value):
            parsed_address = parse_single_address(address_text)
            if parsed_address[0] == ANONYMOUS_URI:
                raise SIPFailure()
            pai_parsed.append(parsed_address)

    if len(pai_parsed) > 2:
        raise SIPFailure()
    if len(pai_parsed) == 2:
        schemes = (pai_parsed[0][1], pai_parsed[1][1])
        if not ((schemes[0] == "sip" and schemes[1] == "tel") or
                (schemes[0] == "tel" and schemes[1] == "sip")):
            raise SIPFailure()

    return {
        "method": method,
        "request_uri": request_uri,
        "from_uri": from_uri,
        "from_scheme": from_scheme,
        "from_tag": from_tag,
        "to_uri": to_uri,
        "to_scheme": to_scheme,
        "to_tag": to_tag,
        "call_id": call_id,
        "cseq": cseq_number,
        "privacy": privacy,
        "content_type": content_type,
        "body": body,
        "ppi": ppi_parsed,
        "rpid": rpid_parsed,
        "pai": pai_parsed,
    }


def _identity_domain(identity):
    """Return the domain component of a canonical directory identity."""
    at = identity.rfind("@")
    if at < 0:
        return ""
    return identity[at + 1:]


def _lookup(alias_map, uri):
    return alias_map.get(uri)


def _authorize_local(parsed, gateway, account, alias_map):
    allowed = set(account.get("allow", ()))
    primary = account["primary"]
    allowed.add(primary)
    local_domains = set(gateway.get("local_domains", ()))

    def resolve_authorized(uri):
        identity = _lookup(alias_map, uri)
        if identity is None:
            raise IdentityFailure()
        if identity not in allowed:
            raise IdentityFailure()
        if _identity_domain(identity) not in local_domains:
            raise IdentityFailure()
        return identity

    from_identity = None
    if parsed["from_uri"] != ANONYMOUS_URI:
        from_identity = resolve_authorized(parsed["from_uri"])

    ppi_identity = None
    if parsed["ppi"] is not None:
        ppi_identity = resolve_authorized(parsed["ppi"][0])

    if ppi_identity is not None:
        selected = ppi_identity
    elif from_identity is not None:
        selected = from_identity
    else:
        selected = primary

    # The selected identity itself must always be allowed and locally hosted.
    if selected not in allowed:
        raise IdentityFailure()
    if _identity_domain(selected) not in local_domains:
        raise IdentityFailure()
    return selected


def _authorize_peer(parsed, gateway, peer_name, alias_map):
    authority = set(gateway.get("peers", {}).get(peer_name, ()))

    def resolve(uri):
        identity = _lookup(alias_map, uri)
        if identity is None:
            raise IdentityFailure()
        return identity

    if not parsed["pai"]:
        # The caller normally handles this as unauthenticated; keep the
        # invariant explicit for safety.
        raise IdentityFailure()

    asserted = None
    for address in parsed["pai"]:
        identity = resolve(address[0])
        if asserted is None:
            asserted = identity
        elif identity != asserted:
            raise IdentityFailure()

    if asserted is None:
        raise IdentityFailure()
    if _identity_domain(asserted) not in authority:
        raise IdentityFailure()

    if parsed["from_uri"] != ANONYMOUS_URI:
        if resolve(parsed["from_uri"]) != asserted:
            raise IdentityFailure()
    if parsed["ppi"] is not None:
        if resolve(parsed["ppi"][0]) != asserted:
            raise IdentityFailure()
    if parsed["rpid"] is not None:
        if resolve(parsed["rpid"][0]) != asserted:
            raise IdentityFailure()
    return asserted


def _build_wire(parsed, identity, private, trusted_out):
    from_uri = ANONYMOUS_URI if private else identity
    from_lines = "From: <" + from_uri + ">"
    if parsed["from_tag"] is not None:
        from_lines += ";tag=" + parsed["from_tag"]

    to_lines = "To: <" + parsed["to_uri"] + ">"
    if parsed["to_tag"] is not None:
        to_lines += ";tag=" + parsed["to_tag"]

    lines = [
        parsed["method"] + " " + parsed["request_uri"] + " SIP/2.0",
        from_lines,
        to_lines,
        "Call-ID: " + parsed["call_id"],
        "CSeq: " + parsed["cseq"] + " " + parsed["method"],
        "Privacy: " + ("id" if private else "none"),
    ]

    if (not private) or trusted_out:
        lines.append("P-Asserted-Identity: <" + identity + ">")
    if parsed["content_type"] is not None:
        lines.append("Content-Type: " + parsed["content_type"])
    lines.append("Content-Length: " + str(len(parsed["body"])))

    return "\r\n".join(lines) + "\r\n\r\n" + parsed["body"]


def _build_alias_map(directory):
    alias_map = {}
    for canonical, aliases in directory.items():
        alias_map[canonical] = canonical
        for alias in aliases:
            alias_map[alias] = canonical
    return alias_map


def _reject(reason):
    return {"status": "reject", "reason": reason}


def process(batch):
    directory = batch.get("directory", {})
    accounts = batch.get("accounts", {})
    gateways = batch.get("gateways", {})
    jobs = batch.get("jobs", [])
    alias_map = _build_alias_map(directory)
    results = []

    for index, job in enumerate(jobs):
        # A source contributes only the previous forwarded wire text.  A
        # rejected predecessor has no wire and yields the distinct upstream
        # reason before any policy for this job is considered.
        if "source" in job:
            source_index = job.get("source")
            if (not isinstance(source_index, int) or
                    isinstance(source_index, bool) or
                    source_index < 0 or source_index >= index or
                    results[source_index].get("status") != "accept"):
                results.append(_reject("upstream"))
                continue
            request_text = results[source_index]["wire"]
        else:
            request_text = job.get("raw")

        try:
            parsed = _parse_request(request_text)
        except SIPFailure:
            results.append(_reject("syntax"))
            continue

        gateway = gateways[job["gateway"]]
        ingress = job["ingress"]
        kind = ingress.get("kind")

        if kind == "local":
            subject = ingress.get("subject")
            if subject not in accounts:
                results.append(_reject("unauthenticated"))
                continue
            try:
                selected = _authorize_local(
                    parsed, gateway, accounts[subject], alias_map
                )
            except IdentityFailure:
                results.append(_reject("identity"))
                continue
            basis = "local"

        elif kind == "peer":
            peer_name = ingress.get("name")
            # A peer is listed in the current gateway's peers map; a global
            # gateway entry alone grants no authority at this boundary.
            if peer_name not in gateway.get("peers", {}):
                results.append(_reject("unauthenticated"))
                continue
            if not parsed["pai"]:
                results.append(_reject("unauthenticated"))
                continue
            try:
                selected = _authorize_peer(
                    parsed, gateway, peer_name, alias_map
                )
            except IdentityFailure:
                results.append(_reject("identity"))
                continue
            basis = "peer"

        elif kind == "untrusted":
            results.append(_reject("unauthenticated"))
            continue
        else:
            # Outer JSON is specified to be well formed.  Treat an impossible
            # ingress kind as having no evidence rather than crashing.
            results.append(_reject("unauthenticated"))
            continue

        private = (
            parsed["from_uri"] == ANONYMOUS_URI or
            parsed["privacy"] == "id"
        )
        trusted_out = bool(job.get("trusted_out"))
        wire = _build_wire(parsed, selected, private, trusted_out)
        results.append({
            "status": "accept",
            "identity": selected,
            "basis": basis,
            "private": private,
            "wire": wire,
        })

    return {"results": results}


def main():
    raw_input = sys.stdin.buffer.read()
    batch = json.loads(raw_input.decode("utf-8"))
    output = process(batch)
    sys.stdout.write(json.dumps(output, ensure_ascii=True, separators=(",", ":")))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
